WITH local_time AS MATERIALIZED (SELECT timezone('Europe/London',clock_timestamp()) AS now), bounds_local AS MATERIALIZED (SELECT CASE $2 WHEN 'today' THEN date_trunc('day',now) WHEN 'yesterday' THEN date_trunc('day',now)-interval '1 day' WHEN 'this-week' THEN date_trunc('week',now) WHEN 'last-week' THEN date_trunc('week',now)-interval '1 week' WHEN 'this-month' THEN date_trunc('month',now) WHEN 'last-month' THEN date_trunc('month',now)-interval '1 month' WHEN 'this-year' THEN date_trunc('year',now) WHEN 'last-year' THEN date_trunc('year',now)-interval '1 year' WHEN 'all-time' THEN timestamp '2000-01-01' WHEN 'custom' THEN $3::date::timestamp END AS from_local, CASE $2 WHEN 'today' THEN date_trunc('day',now)+interval '1 day' WHEN 'yesterday' THEN date_trunc('day',now) WHEN 'this-week' THEN now+interval '1 day' WHEN 'last-week' THEN date_trunc('week',now) WHEN 'this-month' THEN now+interval '1 day' WHEN 'last-month' THEN date_trunc('month',now) WHEN 'this-year' THEN now+interval '1 day' WHEN 'last-year' THEN date_trunc('year',now) WHEN 'all-time' THEN now+interval '1 day' WHEN 'custom' THEN ($4::date+1)::timestamp END AS to_local FROM local_time), bounds AS MATERIALIZED (SELECT from_local AT TIME ZONE 'Europe/London' AS from_at, to_local AT TIME ZONE 'Europe/London' AS to_at FROM bounds_local), account AS MATERIALIZED (SELECT id,steam_name,discord_id FROM public."user" WHERE discord_id=$1 AND discord_id>0 LIMIT 1) SELECT jsonb_build_object('steamName',account.steam_name,'discordId',account.discord_id::text, 'records',(SELECT count(*) FROM (SELECT * FROM public.record WHERE record_eligible) value WHERE value.id_user=account.id AND value.date_created >= bounds.from_at AND value.date_created < bounds.to_at), 'personalBests',(SELECT count(*) FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) value WHERE value.id_user=account.id AND EXISTS(SELECT 1 FROM public.level_item item WHERE item.id_level=value.id_level AND item.deleted=false) AND value.date_created >= bounds.from_at AND value.date_created < bounds.to_at), 'worldRecords',(SELECT count(*) FROM (SELECT * FROM public.world_record_global WHERE record_eligible) value WHERE value.id_user=account.id AND EXISTS(SELECT 1 FROM public.level_item item WHERE item.id_level=value.id_level AND item.deleted=false) AND value.date_created >= bounds.from_at AND value.date_created < bounds.to_at), 'levels',(SELECT count(*) FROM public.level_item value JOIN public."user" author ON author.steam_id=value.author_id WHERE author.id=account.id AND value.deleted=false AND value.created_at >= bounds.from_at AND value.created_at < bounds.to_at), 'votes',(SELECT count(*) FROM public.vote value WHERE value.id_user=account.id AND value.date_created >= bounds.from_at AND value.date_created < bounds.to_at), 'samples',statistics.samples,'distance',statistics.distance,'time',statistics.time, 'averageSpeed',statistics.average_speed,'averageGforce',statistics.average_gforce, 'maxSpeed',statistics.max_speed,'maxGforce',statistics.max_gforce, 'distanceOnTarmac',statistics.tarmac,'distanceOnGrass',statistics.grass, 'distanceOnSand',statistics.sand,'distanceOnSoap',statistics.soap, 'distanceOnWood',statistics.wood,'distanceOnMud',statistics.mud, 'distanceOnIce1',statistics.ice1,'distanceOnIce2',statistics.ice2, 'distanceOnIce3',statistics.ice3,'distanceInAir',statistics.air) AS value FROM account CROSS JOIN bounds CROSS JOIN LATERAL (SELECT count(statistic.id_record) AS samples, COALESCE(sum(statistic.distance),0) AS distance,COALESCE(sum(statistic.time),0) AS time, COALESCE(avg(statistic.average_speed),0) AS average_speed, COALESCE(avg(statistic.average_gforce),0) AS average_gforce, COALESCE(max(statistic.max_speed),0) AS max_speed,COALESCE(max(statistic.max_gforce),0) AS max_gforce, COALESCE(sum(statistic.distance_on_tarmac),0) AS tarmac,COALESCE(sum(statistic.distance_on_grass),0) AS grass, COALESCE(sum(statistic.distance_on_sand),0) AS sand,COALESCE(sum(statistic.distance_on_soap),0) AS soap, COALESCE(sum(statistic.distance_on_wood),0) AS wood,COALESCE(sum(statistic.distance_on_mud),0) AS mud, COALESCE(sum(statistic.distance_on_ice1),0) AS ice1,COALESCE(sum(statistic.distance_on_ice2),0) AS ice2, COALESCE(sum(statistic.distance_on_ice3),0) AS ice3,COALESCE(sum(statistic.distance_in_air),0) AS air FROM public.record_statistic statistic JOIN (SELECT * FROM public.record WHERE record_eligible) record ON record.id=statistic.id_record WHERE record.id_user=account.id AND record.date_created >= bounds.from_at AND record.date_created < bounds.to_at) statistics
